create extension if not exists pgcrypto;
create table organizations(id uuid primary key default gen_random_uuid(), name text not null, currency text not null default 'PKR', created_at timestamptz default now());
create table profiles(id uuid primary key references auth.users on delete cascade, full_name text, job_title text, phone text, created_at timestamptz default now());
create table organization_members(org_id uuid references organizations on delete cascade, user_id uuid references profiles on delete cascade, role text not null check (role in ('Administrator','Project Manager','Site Supervisor','Procurement Officer','Finance Officer','Team Member')), active boolean default true, primary key(org_id,user_id));
create table projects(id uuid primary key default gen_random_uuid(), org_id uuid not null references organizations on delete cascade, name text not null, manager_id uuid references profiles, location text, description text, start_date date, end_date date, budget numeric(16,2) not null check (budget>=0), status text not null default 'Planning' check (status in ('Planning','Active','On Hold','Completed','Archived')), created_at timestamptz default now(), check (end_date>=start_date));
create table project_members(project_id uuid references projects on delete cascade, user_id uuid references profiles, primary key(project_id,user_id));
create table project_milestones(id uuid primary key default gen_random_uuid(), project_id uuid not null references projects on delete cascade, title text not null, due_date date not null, done boolean default false);
create table tasks(id uuid primary key default gen_random_uuid(), project_id uuid not null references projects on delete cascade, title text not null, description text, priority text default 'Medium' check (priority in ('Low','Medium','High','Critical')), status text not null default 'To Do' check (status in ('Backlog','To Do','In Progress','Blocked','Completed')), start_date date, due_date date, effort_hours numeric, pct smallint default 0 check (pct between 0 and 100), created_at timestamptz default now(), check (due_date>=start_date));
create table task_assignees(task_id uuid references tasks on delete cascade, user_id uuid references profiles, primary key(task_id,user_id));
create table task_dependencies(task_id uuid references tasks on delete cascade, depends_on uuid references tasks on delete cascade, primary key(task_id,depends_on), check (task_id<>depends_on));
create table task_comments(id uuid primary key default gen_random_uuid(), task_id uuid not null references tasks on delete cascade, author_id uuid references profiles, body text not null, created_at timestamptz default now());
create table suppliers(id uuid primary key default gen_random_uuid(), org_id uuid not null references organizations on delete cascade, name text not null, contact text);
create table materials(id uuid primary key default gen_random_uuid(), org_id uuid not null references organizations on delete cascade, sku text not null, name text not null, category text, unit text not null, quantity numeric not null default 0 check (quantity>=0), min_stock numeric not null default 0, unit_cost numeric(14,2) not null default 0, supplier_id uuid references suppliers, location text, updated_at timestamptz default now(), unique(org_id,sku));
create table inventory_transactions(id uuid primary key default gen_random_uuid(), material_id uuid not null references materials on delete cascade, project_id uuid references projects, kind text not null check (kind in ('receipt','consumption','adjustment')), quantity numeric not null, created_by uuid references profiles, created_at timestamptz default now());
create table purchase_orders(id uuid primary key default gen_random_uuid(), org_id uuid not null references organizations on delete cascade, project_id uuid references projects, supplier_id uuid references suppliers, status text default 'Requested' check (status in ('Requested','Approved','Ordered','Received','Cancelled')), created_at timestamptz default now());
create table purchase_order_items(id uuid primary key default gen_random_uuid(), po_id uuid not null references purchase_orders on delete cascade, material_id uuid references materials, quantity numeric not null check (quantity>0), unit_cost numeric(14,2) not null);
create table budgets(id uuid primary key default gen_random_uuid(), project_id uuid not null references projects on delete cascade, category text not null, original numeric(16,2) not null, revised numeric(16,2));
create table expenses(id uuid primary key default gen_random_uuid(), project_id uuid not null references projects on delete cascade, category text not null, vendor text, expense_date date not null, amount numeric(16,2) not null check (amount>0), status text not null default 'Pending' check (status in ('Paid','Pending')), reference text, notes text, created_at timestamptz default now());
create table documents(id uuid primary key default gen_random_uuid(), project_id uuid not null references projects on delete cascade, name text not null, category text, storage_path text not null, version int default 1, uploaded_by uuid references profiles, created_at timestamptz default now());
create table activity_logs(id uuid primary key default gen_random_uuid(), org_id uuid not null references organizations on delete cascade, actor_id uuid, message text not null, created_at timestamptz default now());
create table notifications(id uuid primary key default gen_random_uuid(), user_id uuid not null references profiles, message text not null, read boolean default false, created_at timestamptz default now());
create index on projects(org_id); create index on tasks(project_id); create index on expenses(project_id); create index on materials(org_id);

-- Row Level Security: access only through organization membership
create function is_member(o uuid) returns boolean language sql stable security definer as $$ select exists(select 1 from organization_members where org_id=o and user_id=auth.uid() and active) $$;
alter table organizations enable row level security; create policy org_r on organizations for select using (is_member(id));
alter table projects enable row level security; create policy p_all on projects for all using (is_member(org_id)) with check (is_member(org_id));
alter table materials enable row level security; create policy m_all on materials for all using (is_member(org_id)) with check (is_member(org_id));
alter table suppliers enable row level security; create policy s_all on suppliers for all using (is_member(org_id)) with check (is_member(org_id));
alter table purchase_orders enable row level security; create policy po_all on purchase_orders for all using (is_member(org_id)) with check (is_member(org_id));
alter table activity_logs enable row level security; create policy a_r on activity_logs for select using (is_member(org_id));
do $$ declare t text; begin foreach t in array array['tasks','expenses','budgets','documents','project_milestones'] loop
 execute format('alter table %I enable row level security', t);
 execute format('create policy %I on %I for all using (is_member((select org_id from projects where id=project_id))) with check (is_member((select org_id from projects where id=project_id)))', t||'_org', t); end loop; end $$;
